//! Lane tables of the horizon-legacy-join mod: packet id maps between each
//! lane (the protocol on the wire, e.g. 763 = 1.20.1) and the engine's inner
//! session numbering (upstream's V1_20_3, protocol 765), per state.
//!
//! `table_up`'s array is indexed by the lane's own id and holds the inner
//! session's id for the same packet; `table_down` is the reverse. The
//! committed file is what a released .hnmod ships; tools/generate_data.py
//! regenerates the marker section (name-matched against the adapter's own
//! packet names and id tables).
//!
//! Fallback for any lane without generated tables: identity over 0..=255 —
//! right for status and login (which share ids across those eras), an
//! approximation on play (the game tolerated-skips what it cannot decode),
//! and the point the pipeline keeps getting refined against.

/// Whether a lane has tables this mod knows: protocol 763 = 1.20.1 in
/// alpha-1. The engine consults this to accept or refuse a protocol.
pub fn covers(protocol: i32) -> bool {
    protocol == 763
}

/// The lane -> inner id map for one state of one lane (clientbound side).
pub fn table_up(protocol: i32, state: u8) -> &'static [Option<u8>; 256] {
    match (protocol, state) {
        (763, 0) => &LANE_763_HANDSHAKE_CB,
        (763, 1) => &LANE_763_STATUS_CB,
        (763, 2) => &LANE_763_LOGIN_CB,
        (763, 3) => &LANE_763_CONFIG_CB,
        (763, 4) => &LANE_763_PLAY_CB,
        _ => &IDENTITY,
    }
}

/// The inner -> lane id map for one state of one lane (serverbound side).
pub fn table_down(protocol: i32, state: u8) -> &'static [Option<u8>; 256] {
    match (protocol, state) {
        (763, 0) => &LANE_763_HANDSHAKE_SB_DOWN,
        (763, 1) => &LANE_763_STATUS_SB_DOWN,
        (763, 2) => &LANE_763_LOGIN_SB_DOWN,
        (763, 3) => &LANE_763_CONFIG_SB_DOWN,
        (763, 4) => &LANE_763_PLAY_SB_DOWN,
        _ => &IDENTITY,
    }
}

